Record Envio
  Define estado, repartidor, motivo As String;
  Define hora As Integer;
EndRecord

Algorithm Envios
  Define estado As String;
  Read estado;
  Define envio As Envio <- Envio(estado, "", "", 0);
  If estado = "en camino" Then
    Read envio.repartidor;
    Write "En camino con ", envio.repartidor;
  Else
    If estado = "cancelado" Then
      Read envio.motivo;
      Write "Cancelado: ", envio.motivo;
    Else
      Write "Pendiente";
    EndIf
  EndIf
EndAlgorithm

