evaluation.reference:
Variant Envio
  Case Pendiente
  Case EnCamino(repartidor As String)
  Case Cancelado(motivo As String)
  Case Desconocido(estado As String)
EndVariant

Function texto <- Describir(envio As Envio)
  Define texto As String <- "";
  Switch envio Do
    Envio.Pendiente: texto <- "Pendiente";
    Envio.EnCamino(quien): texto <- "En camino con " + quien;
    Envio.Cancelado(motivo): texto <- "Cancelado: " + motivo;
    Envio.Desconocido(estado): texto <- "Estado desconocido: " + estado;
  EndSwitch
EndFunction

Algorithm Envios
  Define estado, dato As String;
  Read estado;
  Define envio As Envio <- Envio.Desconocido(estado);
  If estado = "pendiente" Then
    envio <- Envio.Pendiente;
  EndIf
  If estado = "en camino" Then
    Read dato;
    envio <- Envio.EnCamino(dato);
  EndIf
  If estado = "cancelado" Then
    Read dato;
    envio <- Envio.Cancelado(dato);
  EndIf
  Write Describir(envio);
EndAlgorithm
